import {section,table,cite,topic,mountTopic,rangePlayback} from './topic-tools.js';
import {texEq as eq} from './math.js';
import {bpeTraining,segmentationLattice,selectSegmentation,toyPieces} from './tokenization-model.js';
export const tokenizationSections=[['units','Choose the unit before the model'],['bpe','BPE learns an ordered merge list'],['merge-lab','Watch the vocabulary grow'],['bytes','Bytes are not characters'],['chunks','Pre-tokenization restricts merges'],['control','Special tokens and normalization'],['unigram','Score complete segmentations'],['lattice','Maximum versus sum'],['sampling','Sample boundaries, not text'],['patches','BLT: spend large-model work on patches'],['concepts','LCM: predict sentence representations'],['evaluation','Measure the whole representation contract'],['sources','Sources and connected notes']];
export const tokenizationMeta={slug:'models/tokenization',title:'Tokenization and Input Representations',description:'From ordered BPE merges to probabilistic segmentation, dynamic byte patches and sentence-level concepts: what each unit preserves and costs.',date:'2026-04-08',updated:'2026-10-12',topicPath:['models','representations'],tags:['BPE','BytePiece','unigram','Viterbi','subword regularization','BLT','SONAR','LCM','bits per byte'],prototype:true,visibility:'public',kind:'dense-topic',learningGoals:['Separate reversible encoding from a learned semantic bottleneck','Derive best-path and sampled segmentations','Compare token, byte, patch and concept computation fairly'],related:['models/attention','math/information','execution/decoding']};
export const tokenizationAliases=[];
const mergeFrames=bpeTraining(['low','lower','lowest'],5);
const exampleLattice=segmentationLattice('aba',toyPieces);
const mergeWords=frame=>frame.corpus.map(w=>`<div class="token-piece-row">${w.map(s=>`<span>${s}</span>`).join('')}</div>`).join('');
const segmentRows=alternatives=>alternatives.map(a=>`<div class="probability-row"><span>${a.pieces.join(' | ')}</span><div class="probability-track" aria-hidden="true"><i style="width:${a.probability*100}%"></i></div><span class="probability-value">${a.probability.toFixed(3)}</span></div>`).join('');
const mergeTrace=`<details><summary>All six merge states</summary><p>Counts below are measured before replacement. The first merge removes three symbol occurrences, one in each word. Later counts use the newly segmented corpus.</p>${table('Complete toy BPE trace',['Step and selected pair','Segmented words'],mergeFrames.map((f,i)=>[i===0?'0 · Initial symbols':`${i} · ${f.pair.join(' + ')}<br>${f.count} adjacent occurrences`,f.corpus.map(w=>`<span style="white-space:nowrap">${w.join(' | ')}</span>`).join('<br>')])).replace('<div class="dense-table-wrap">','<div class="dense-table-wrap" role="region" aria-label="Complete toy BPE trace" tabindex="0">').replace('<table>','<table style="min-width:360px">')}</details>`;
const mergeLab=`<div id="merge-lab" class="topic-scene" data-merge-lab><h3>One merge changes the next count</h3><p>Toy corpus: low, lower, lowest. Characters are the initial symbols. Ties use lexicographic pair order.</p><label>Training progress<input type="range" min="0" max="100" step="1" value="0" aria-label="BPE merge progress"></label><div data-merge-words>${mergeWords(mergeFrames[0])}</div><p data-merge-caption>0 / Start with individual symbols.</p><div class="scene-stats">Symbols across the corpus: <output data-symbol-count>${mergeFrames[0].corpus.flat().length}</output></div><div class="dense-actions"><button data-play type="button">Play</button><button data-reset type="button">Replay</button></div><p class="topic-scenes-caption">Each count uses the current segmentation. This is a small character-level illustration, not a production tokenizer or measured compression benchmark.</p></div>`;
const latticeLab=`<div id="lattice" class="topic-scene" data-lattice-lab><h3>Three paths spell the same bytes</h3><p>Input aba. Piece weights: a=.4, b=.3, ab=.2, ba=.1. The highest-weight path is ab | a; sampling can choose any path.</p><p>The path weights are .048 for a | b | a, .040 for a | ba and .080 for ab | a. Their sum is .168. Divide each weight by this sum to obtain the probabilities below; displayed values are rounded.</p><div class="probability-rows" data-segment-rows>${segmentRows(exampleLattice.alternatives)}</div><label>Uniform draw position<input type="range" min="0" max="100" step="1" value="50" aria-label="Segmentation quantile"></label><p>Selected path: <output data-selected-path>${selectSegmentation(exampleLattice.alternatives,.5).pieces.join(' | ')}</output></p><p class="topic-scenes-caption">Moving this control selects a quantile, not a random experiment. A truly uniform draw over [0,1) samples the displayed probabilities. Every path reconstructs aba exactly.</p></div>`;
export function tokenizationReader(link){return topic(tokenizationMeta,tokenizationSections,'Changing the unit changes the work, the information and the errors.',`
<p>A model sees neither words nor meaning directly. Its input interface chooses units, maps them to numbers, and determines how much computation each span receives. Most language models use fixed subword IDs. Other architectures keep bytes accessible or move the expensive computation to larger learned representations.</p><p>The key distinction is what the interface promises. A reversible tokenizer changes the segmentation without losing the original text. A sentence embedding can preserve useful meaning while losing exact spelling, formatting or details. These are different contracts, not merely different compression ratios.</p>
${section('units','Choose the unit before the model',`${table('A representation is also a compute allocation',['Unit','What the large model processes','Main boundary'],[['Subword token','One fixed vocabulary ID per piece','Vocabulary and merge rules'],['Raw byte','One of 256 values at each step','Longer sequences; UTF-8 characters can span bytes'],['BLT patch','A learned representation of a dynamic byte group','Local byte models remain necessary'],['LCM concept','A SONAR sentence representation','Semantic encoding is not exact text serialization']])}<p>Shorter sequences can reduce attention, MLP and KV work. A larger vocabulary increases embedding and output-head cost. A latent interface adds encoder/decoder costs. Count the complete path, not only the central transformer.</p>`)}
${section('bpe','BPE learns an ordered merge list',`<p>Byte Pair Encoding repeatedly replaces a frequent adjacent symbol pair with a new symbol. The next frequency count runs on the changed segmentation. The resulting vocabulary stores reusable substrings, not a dictionary of complete words.</p><pre><code>symbols = initial_symbols(corpus)
merges = []
while vocabulary_size(symbols) &lt; target_size:
    pair = most_frequent_adjacent_pair(symbols)
    symbols = merge_nonoverlapping(symbols, pair)
    merges.append(pair)</code></pre><p>Training learns the ordered rules. Encoding applies their ranks to new input; it does not learn new frequencies from that input. Pretokenization boundaries restrict where a merge may occur. Define tie-breaking and overlap handling to reproduce a trained tokenizer.</p>${mergeLab}${mergeTrace}<p>BPE began as a compression technique in 1994 and was adapted to neural translation subwords in 2015–2016. Unigram segmentation and subword regularization supply a different probability-based route. The later BytePiece, BLT and LCM approaches change training or representation assumptions rather than simply extending one merge list.</p>`)}
${section('bytes','Bytes are not characters',`<p>Character-level vocabularies must cover their alphabet or provide a fallback. Byte-level BPE starts with all 256 byte values. It can represent arbitrary byte sequences without an unknown symbol, provided the implementation preserves those base entries.</p><pre><code>é  → c3 a9          # Two UTF-8 bytes
🙂 → f0 9f 99 82    # Four UTF-8 bytes</code></pre><p>A token can contain only part of a multibyte character. Decode the full byte stream with an explicit Unicode error policy. Arbitrary representable bytes are not necessarily valid UTF-8 text.</p><p>Rare scripts can still require many pieces even with complete byte coverage. Byte-level encoding guarantees representability, not equal cost across languages or universal robustness to typos.</p>`)}
${section('chunks','Pre-tokenization restricts merges',`<p>A regex can split text into chunks before BPE. This prevents learned merges from freely crossing letters, numbers, punctuation and whitespace. A leading space can remain attached to a word chunk: hello and “ hello” need not receive the same IDs.</p><details><summary>Historical GPT-2 and cl100k-style regexes</summary><pre><code>GPT-2: 's|'t|'re|'ve|'m|'ll|'d| ?\\p{L}+| ?\\p{N}+| ?[^\\s\\p{L}\\p{N}]+|\\s+(?!\\S)|\\s+
cl100k: (?i:'s|'t|'re|'ve|'m|'ll|'d)|[^\\r\\n\\p{L}\\p{N}]?\\p{L}+|\\p{N}{1,3}| ?[^\\s\\p{L}\\p{N}]+[\\r\\n]*|\\s*[\\r\\n]+|\\s+(?!\\S)|\\s+</code></pre><p>These patterns require Unicode property support, not Python's ordinary re module. Pin the exact implementation and tokenizer artifact instead of copying a family label.</p></details>${table('Why the chunk rules matter',['Rule','Effect'],[['Contraction alternatives','Separate common English suffixes; cl100k form is case-insensitive'],['Optional leading space / prefix','Distinguishes word starts and avoids arbitrary cross-word merges'],['Digits in groups of 1–3','Restricts large numeric chunks; not a proof of better arithmetic'],['Punctuation and newline branches','Controls code, Markdown and line-ending behavior'],['Whitespace lookahead','Handles trailing whitespace differently from ordinary runs']])}<p>Use matching chunk rules at training and inference. Evaluate individual-digit and grouped-digit designs on number tasks. Preserve indentation and line endings for code. Train the vocabulary on the intended code, math and language mixture, not only convenient English prose.</p>`)}
${section('control','Special tokens and normalization',`<p>BOS, EOS, padding, role delimiters, tool markers and fill-in-the-middle markers are normally reserved separately from ordinary merges. Raw text that looks like a control marker must not silently become that control ID unless the caller permits it.</p><p>This boundary prevents accidental control-token injection. It does not solve semantic prompt injection, which can happen entirely through ordinary words. Keep text encoding, chat-template serialization and allowed special tokens separate.</p><p>Lowercasing, trimming and Unicode normalization can change or remove source bytes. State whether decode(encode(x)) reproduces raw x or only its normalized form. A reversible byte tokenizer cannot restore text already discarded by preprocessing.</p><p>Freeze IDs and vocabulary before pretraining. Changing ID meanings breaks embedding/output semantics. Adding reserved tokens later requires initialization and usually continued training. Version the tokenizer together with the model and chat template.</p>`)}
${section('unigram','Score complete segmentations',`<p>BPE chooses ranked merges. A unigram-style tokenizer assigns piece weights and scores a complete segmentation by the product of those weights. BytePiece uses a byte-based n-gram discovery/training scheme; it is not simply a renamed BPE merge trainer.</p>${eq(String.raw`\begin{aligned}w(z_{1:n})&=\prod_{i=1}^np(z_i)\\z^*&=\operatorname*{arg\,max}_{z:\,\operatorname{concat}(z)=x}\sum_i\log p(z_i)\end{aligned}`,'This tokenizer likelihood is not the language model’s probability of a sentence. Minimizing piece negative log weights need not minimize the number of pieces.')}
<p>The length-compression objective—few tokens per byte under a manageable vocabulary—is useful, but it is not sufficient. A tokenizer's length reduction is not an entropy coder's bit count. IDs, vocabulary storage, output dimension and downstream model quality all have costs.</p><p>Compare the families carefully: BPE learns frequent pair merges; WordPiece uses a different vocabulary/scoring scheme and often ## continuation markers; unigram tokenization scores paths through a piece vocabulary. SentencePiece is a tokenizer framework that supports both BPE and unigram, not one segmentation algorithm.</p>`)}
${section('sampling','Sample boundaries, not text',`<p>Let t be a byte boundary. Every valid piece x[s:t] is an edge from s to t. The best segmentation is a maximum-weight path through this directed acyclic graph.</p>${eq(String.raw`\begin{aligned}D[0]&=0,\qquad D[t]=\max_{s<t:\,x[s:t]\in\mathcal V}\left(D[s]+\log p(x[s:t])\right)\\Z[0]&=1,\qquad Z[t]=\sum_{s<t:\,x[s:t]\in\mathcal V}Z[s]p(x[s:t])\end{aligned}`,'Only vocabulary pieces create edges. Unreachable best-path states are −∞; unreachable sum states are zero. Use log-sum-exp for long strings.')}
<p>The maximum gives Viterbi decoding. Replacing max with sum gives the weight of all paths into each boundary. Then sample a predecessor boundary and continue backward. The telescoping factors give each complete path weight divided by Z[end].</p>${eq(String.raw`\Pr(s\mid t,x)=\frac{Z[s]p(x[s:t])}{Z[t]},\qquad \Pr(z\mid x)=\frac{\prod_i p(z_i)}{Z[|x|]}`,"For valid vocabulary edges and a reachable boundary Z[t]>0. The empty path at boundary zero has weight one; nonempty input needs at least one complete path.")}${latticeLab}<p>Randomized segmentations expose the language model to alternate boundaries for the same text. This is subword regularization: an augmentation of the input representation, not a new paraphrase. Robustness improvements require downstream tests; alternate pieces can also change lengths and batch composition.</p><p>The dynamic-programming state is linear in input length. Runtime depends on candidate edges and vocabulary matching, not just the number of boundaries. Enumeration in the toy visual is deliberately tiny; a production sampler should not enumerate exponentially many full paths.</p>`)}
${section('patches','BLT: spend large-model work on patches',`<p>Byte Latent Transformer keeps raw bytes accessible while grouping them into dynamic patches. A small causal byte predictor estimates next-byte uncertainty. Thresholds create patch boundaries; high uncertainty can mean more frequent large-model work.</p><p>A boundary is not a proven semantic-unit detector. The decision must be available from the prefix during generation, not from future bytes. BLT distinguishes absolute-entropy and relative-entropy rules; neither is simply “split at spaces.”</p><div class="spec-architecture"><div>Bytes → local encoder</div><span>↓</span><div>Patch representations → large global transformer</div><span>↓</span><div>Local autoregressive decoder → bytes</div></div><p>Patch queries pool local byte features; the decoder uses byte queries over patch context. This cross-attention interface is not the global transformer directly reading all raw bytes. Byte decoding remains autoregressive.</p><p>The source's 100M-local/7B-global figures are illustrative configurations, not mandatory sizes. FLOP-controlled comparisons with Llama 3 motivate the architecture. Larger predictable patches can amortize large-model work, but local processing, entropy prediction and implementation overhead remain. A favorable FLOP curve does not guarantee faster wall-clock decoding.</p><p>${cite('https://arxiv.org/abs/2412.09871','BLT paper')} provides the architecture and scaling conditions. It does not imply that ordinary BPE always treats “photosynthesis” as one token or that every patch starts a new semantic unit.</p>`)}
${section('concepts','LCM: predict sentence representations',`<p>Large Concept Models move the global model to SONAR sentence embeddings. Segment text, encode each sentence, predict a next representation, then decode it into a supported language. Diffusion can generate continuous embeddings; residual vector quantization instead generates coarse-to-fine discrete codes.</p><div class="spec-architecture"><div>Sentences → SONAR encoder</div><span>↓</span><div>Concept sequence → next-concept model</div><span>↓</span><div>SONAR decoder → supported text language</div></div><p>These vectors are learned sentence representations, not guaranteed atomic meanings. Shared multilingual geometry does not prove perfect language invariance, human-like reasoning or arbitrary modality decoding. Token-by-token models can also learn planning.</p><p>The source discusses spaCy and SaT segmentation. The paper uses capped SaT preparation to avoid overly long spans. A generated concept sequence from an English prompt can be decoded into French if the SONAR decoder supports that language. This avoids generating an English intermediary, but does not guarantee lossless translation. Check reconstruction, named entities, numbers, code and factual details. A shorter central sequence cannot restore information lost in the semantic bottleneck.</p><p>Include sentence encoding and text decoding in compute comparisons. Do not assume every sentence costs one cheap operation: diffusion, quantization and reconstruction add work. ${cite('https://arxiv.org/abs/2412.08821','LCM paper')} discusses embedding-space fragility and representation mismatch. The benefits and limitations differ from reversible subword encoding.</p>`)}
${section('evaluation','Measure the whole representation contract',`${table('Before committing to a tokenizer or representation',['Check','Why it matters'],[['Exact byte round-trip and invalid UTF-8 policy','Coverage is not the same as reversible preprocessing'],['Per-language fertility, bytes/token, pieces/word and split-word rate','Aggregate English compression can hide unequal sequence cost; fertility counts pieces per word/span'],['Code lines, JSON, Markdown, Unicode, typos','Whitespace and rare bytes reveal hidden interface failures'],['Digit chunks and copy/edit tasks','Compression can conflict with compositional arithmetic or exact copying'],['Vocabulary/head memory and total sequence work','Shorter input can buy a larger output projection'],['Special-token and chat-template collision tests','Content IDs must remain distinct from control serialization'],['Downstream trained-model quality and throughput','Tokenizer-only metrics do not establish model superiority'],['Latent reconstruction and full encoder/decoder cost','A lossy bottleneck needs different evidence from byte coverage']])}${eq(String.raw`\operatorname{BPB}=-\frac{\sum_t\log_2q(z_t\mid z_{<t})}{\text{number of source bytes}}`,'For a deterministic reversible tokenization, this expresses ideal coding cost per raw byte under that chosen token path. Keep bytes, formatting, context and evaluation data fixed.')}
<p>Per-token perplexity changes with the unit. It is not directly comparable across tokenizers. Bits per byte gives a common denominator, but one chosen segmentation's score is not generally the probability marginal over every token sequence that decodes to the same text. State the scoring convention, and evaluate sampled training segmentation under a fixed test policy.</p><p>Measure unknown-token rate too: it should be zero for a complete byte vocabulary under the stated preprocessing contract. Track tokens per code line and the proportion of words split into multiple pieces. A concept reconstruction score is not automatically a likelihood over source bytes. Do not present its semantic distance or autoencoding quality as BPB without a probabilistic text-decoding path.</p><p><a href="${link('math/information')}">Information Theory →</a> explains coding cost. <a href="${link('models/attention')}">Attention →</a> explains how sequence length changes cache and operator costs.</p>`)}
${section('sources','Sources and connected notes',`<p>${cite('https://aclanthology.org/P16-1162/','BPE for neural translation')} · ${cite('https://github.com/bojone/bytepiece','BytePiece implementation')} · ${cite('https://kexue.fm/archives/9752','BytePiece training article')} · ${cite('https://kexue.fm/archives/9768','Viterbi sampling article')} · ${cite('https://github.com/openai/tiktoken/blob/main/tiktoken_ext/openai_public.py','Tokenizer regex definitions')}</p><div class="dense-related"><a href="${link('models/attention')}">Attention →</a><a href="${link('math/information')}">Information Theory →</a><a href="${link('training/frontier-recipes')}">Model recipes →</a><a href="${link('training/scaling')}">Scaling →</a><a href="${link('models/vision')}">Representation Learning →</a></div>`)}
`);}
tokenizationMeta.searchText=tokenizationReader(()=> '').replace(/<[^>]*>/g,' ');
export function mountTokenization(scope=document){mountTopic(scope,tokenizationMeta.slug,article=>{
 const lab=article.querySelector('[data-merge-lab]'),frames=mergeFrames;
 rangePlayback(article,lab,value=>{const n=Math.min(frames.length-1,Math.floor(value/100*frames.length)),f=frames[n];lab.querySelector('[data-merge-words]').innerHTML=mergeWords(f);lab.querySelector('[data-merge-caption]').textContent=n===0?'0 / Start with individual symbols.':`${n} / Merge ${f.pair.join(' + ')} → ${f.pair.join('')} · counted ${f.count} times before replacement.`;lab.querySelector('[data-symbol-count]').textContent=f.corpus.reduce((s,w)=>s+w.length,0);},14000);
 const lattice=exampleLattice,paths=article.querySelector('[data-lattice-lab]');const slider=paths.querySelector('input');const draw=()=>{paths.querySelector('[data-selected-path]').textContent=selectSegmentation(lattice.alternatives,Number(slider.value)/100).pieces.join(' | ');};slider.addEventListener('input',draw);draw();
});}
